/** La T sola. Proporción 100×96: pasale alto o ancho por className. */
export function IsotipoTropero({
  className,
  color = 'currentColor',
  title,
}: {
  className?: string
  color?: string
  title?: string
}) {
  return (
    <svg
      viewBox="0 0 100 96"
      className={className}
      role={title ? 'img' : undefined}
      aria-hidden={title ? undefined : true}
    >
      {title && <title>{title}</title>}
      <path d={ISOTIPO_D} style={{ fill: color }} />
    </svg>
  )
}

/**
 * Logo horizontal: T + "Tropero". La T va del color de `iso` (trigo sobre
 * monte, campo sobre claro) y la palabra del de `palabra`.
 */
export function LogoTropero({
  className,
  iso = MARCA_COLOR.trigo,
  palabra = MARCA_COLOR.hueso,
  title = 'Tropero',
}: {
  className?: string
  iso?: string
  palabra?: string
  title?: string
}) {
  return (
    <svg viewBox="0 -681.15 4631.68 867.19" className={className} role="img">
      <title>{title}</title>
      <path transform="translate(0 -651.88) scale(6.79045)" d={ISOTIPO_D} style={{ fill: iso }} />
      <path transform="translate(1057.55 0)" d={WORDMARK_D} style={{ fill: palabra }} />
    </svg>
  )
}
